// Cosine similarity: the only equation this lesson needs (plain JS)
function cosine(a, b) {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return na && nb ? dot / (Math.sqrt(na) * Math.sqrt(nb)) : 0;
}
// Toy vectors (NOT real embeddings — geometry demo only):
// refund ~ reimbursement (nearby), refund vs SKU (orthogonal by construction)
const refund = [0.9, 0.1, 0.0], reimburse = [0.85, 0.15, 0.05], sku = [0.0, 0.05, 0.95];
// cosine(refund, reimburse) ≈ 0.996 (paraphrase wins)
// cosine(refund, sku) ≈ 0.05 (exact tokens need lexical rescue → Ch.4)

